function createBarChart(data: number[]) {
  const svg = d3.select("body").append("svg");
  const width = 500;
  const height = 300;
  const barWidth = 50;
  const barHeight = 20;

  const xScale = d3
    .scaleLinear()
    .domain([0, d3.max(data)])
    .range([0, width]);

  const yScale = d3
    .scaleBand()
    .domain(data.map((_, i) => i))
    .range([0, height])
    .padding(0.1);

  svg
    .attr("width", width)
    .attr("height", height)
    .selectAll("rect")
    .data(data)
    .enter()
    .append("rect")
    .attr("x", (d, i) => xScale(d))
    .attr("y", (d, i) => yScale(i))
    .attr("width", barWidth)
    .attr("height", barHeight);
}
```

