function lengthOfLongestSubstring(s: string): number {
  let max = 0;
  let start = 0;
  let end = 0;
  let map = new Map();

  while (end < s.length) {
    const char = s[end];
    if (map.has(char)) {
      start = Math.max(map.get(char) + 1, start);
    }
    map.set(char, end);
    max = Math.max(max, end - start + 1);
    end++;
  }

  return max;
}
```

