function validateTanzaniaTelephoneNumber(number: string): boolean {
  const digits = number.split("").map((digit) => parseInt(digit));
  const sum = digits.reduce((acc, digit, index) => {
    if (index % 2 === 0) {
      return acc + digit;
    } else {
