function SecureCopy(buffer: Uint8Array, src: number, dst: number, dst_end: number) {
    const diff = dst - src;
    const length = dst_end - dst;
    let len = length;

    if (diff >= BLOCK_COPY_LIMIT) {
        if (diff >= length) {
            buffer.subarray(dst).set(buffer.subarray(src, src + length));
            return length;
        }
