        buffer[dst + 1] = buffer[src + 1];
        buffer[dst + 2] = buffer[src + 2];
        buffer[dst + 3] = buffer[src + 3];
        dst += 4;
        src += 4;
        len -= 4;
    }
    while (len-- > 0) {
        buffer[dst++] = buffer[src++];
    }
    return length;
}

