function findMethodPositions(tree: ts.SourceFile, filePath: string, methodName: string): [number, number] {
  const sourceFile = ts.createSourceFile(filePath, tree.getFullText(), ts.ScriptTarget.Latest);
  const methodDeclaration = sourceFile.statements.find(
    (statement) => statement.kind === ts.SyntaxKind.MethodDeclaration && statement.name.getText() === methodName
  );
  if (!methodDeclaration) {
    return [0, 0];
  }
  const methodBody = methodDeclaration.body;
  if (!methodBody) {
    return [0, 0];
  }
  const methodStart = methodDeclaration.pos;
  const methodEnd = methodBody.pos + methodBody.end - methodDeclaration.pos;
  return [methodStart, methodEnd];
}
