  await Promise.all(tables.map((table) => table.remove()));

  const sections = await Section.find({ companyId });
  await Promise.all(sections.map((section) => section.remove()));

  const scoreItems = await ScoreItem.find({ companyId });
  await Promise.all(scoreItems.map((scoreItem) => scoreItem.remove()));
}
