function recursion(
  left: TreeNode<number> | null,
  right: TreeNode<number> | null
): boolean {
  if (left == null || right == null) {
    return left == null && right == null;
  }
  return (
    left.val === right.val &&
    recursion(left.left, right.right) &&
    recursion(left.right, right.left)
  );
}

