async function getStats(accessToken: string, username: string): Promise<Stats> {
  const repos = await fetchRepos(accessToken, username);
  const langs = await Promise.all(
    repos.map(async (repo) => {
      const langs = await fetchLanguages(accessToken, repo.name);
      return {
        name: repo.name,
        usageNum: langs.length,
      };
    })
  );
  const commits = await Promise.all(
    repos.map(async (repo) => {
      const commits = await fetchCommits(accessToken, repo.name);
      return commits.length;
    })
  );
  const totalCommits = commits.reduce((a, b) => a + b, 0);
  const totalRepos = repos.length;
  const mostUsedLangs = langs
    .sort((a, b) => b.usageNum - a.usageNum)
    .slice(0, 3);
  return {
    totalCommits,
    totalRepos,
    mostUsedLangs,
  };
}
```

