     *  altered == -1
     *  alteredOct == -1
     */
    const chroma = either(
      (semitonesAltered - toSemitones(octavesAltered) + 12) % 12,
      semitonesAltered % 12,
      ltz(octavesAltered),
    ) as NoteChroma;

    const midi = (toSemitones(octave) + chroma) as NoteMidi;

    const frequency = toFrequency(midi, tuning) as NoteFreq;

