                } else {
                    if (board.tiles[x][startY] === "") {
                        ended = true;
                    }
                }
            }

            return [new Play(startX, startY, direction, letters), PlayError.None];
        } else {
            let ended = false;

            for (let y = startY + 1; y < 15; y++) {
                if (scratchBoard.tiles[startX][y] !== "") {
                    if (ended) {
