function format(n: number | string): string {
  const s = n.toString();
  const parts = [];
  for (let i = s.length - 1; i >= 0; i--) {
    parts.unshift(s[i]);
    if ((s.length - i) % 3 === 0 && i !== 0) {
      parts.unshift(",");
    }
  }
  return parts.join("");
}
