    mtime_unix: stats.mtime.toUTCString(),
    mtime_ms: stats.mtimeMs.toString(),
    inode: stats.ino.toString(),
    size: stats.size.toString(),
  });

  return fingerprintCache.obtain(cacheKey, () => contentFingerprintMiss(file));
}

