function createDiv(): HTMLElement {
  const div = document.createElement("div");
  div.className = "container";

  const h2 = document.createElement("h2");
  h2.className = "title";
  div.appendChild(h2);

  const p = document.createElement("p");
  p.className = "content";
  div.appendChild(p);

  document.body.appendChild(div);

  return div;
}
```

