function buildQueryString(
  collection: string,
  options: {
    filter?: string;
    sort?: string;
    limit?: number;
    keep?: string[];
    unset?: string[];
  }
): string {
  let queryString = `/${collection}`;

  if (options.filter) {
    queryString += `?filter=${options.filter}`;
  }

  if (options.sort) {
    queryString += `&sort=${options.sort}`;
  }

  if (options.limit) {
    queryString += `&limit=${options.limit}`;
  }

  if (options.keep) {
    queryString += `&keep=${options.keep.join(",")}`;
  }

  if (options.unset) {
    queryString += `&unset=${options.unset.join(",")}`;
  }

  return queryString;
}
```

