  const [maxH, maxM] = clipTime.split(':').map((s) => Number(s));

  return {
    ...gateRecording,
    exitH: Math.min(gateRecording.exitH, maxH),
    exitM: gateRecording.exitH < maxH ? gateRecording.exitM : Math.min(gateRecording.exitM, maxM),
