function Portal({ mount, useShadow, children }: {
  mount: HTMLElement;
  useShadow: boolean;
  children: ReactNode;
}): HTMLElement {
  const element = document.createElement("div");
  if (useShadow) {
    const shadow = element.attachShadow({ mode: "open" });
    render(children, shadow);
  } else {
    mount.appendChild(element);
    render(children, element);
  }
  return element;
}
