async function partition(arr: number[], pivot: number): Promise<number> {
  let left = 0;
  let right = arr.length - 1;

  while (left < right) {
    if (arr[left] < pivot) {
      left++;
    } else if (arr[right] >= pivot) {
      right--;
    } else {
      swap(arr, left, right);
    }
  }

  return left;
}

function swap(arr: number[], i: number, j: number) {
  const temp = arr[i];
  arr[i] = arr[j];
  arr[j] = temp;
}
