  if (!model.properties) {
    return [];
  }

  return Object.keys(model.properties).reduce(
    (properties, propertyName): ApiModelProperties[] => {
      const property = model.properties[propertyName];

      if (!!property.$ref) {
        properties.push({
          name: propertyName,
          type: getModelNameFromFullReference(property.$ref),
          required: isRequired(model, propertyName)
        });
      } else if (!!property.items) {
        if (!!property.items.$ref) {
          properties.push({
            name: propertyName,
            type: `${getModelNameFromFullReference(property.items.$ref)}[]`,
            required: isRequired(model, propertyName)
          });
        } else if (!!property.items.type) {
          properties.push({
            name: propertyName,
            type: `${mapType(property.items.type)}[]`,
            required: isRequired(model, propertyName)
          });
        }
      } else if (!!property.type) {
        properties.push({
          name: propertyName,
          type: mapType(property.type),
          required: isRequired(model, propertyName)
        });
      }
      return properties;
    },
    [] as ApiModelProperties[]
  );
}

