            case Opcode.HCF:
                break;
            case Opcode.ADD:
            case Opcode.MUL:
            case Opcode.LT:
            case Opcode.EQ:
                parameters.push({
                    mode: parameterModes[0],
                    value: memory[instructionPtr++],
