function networkRank(n: number, roads: number[][]): number {
  const graph: number[][] = Array.from({ length: n }, () => []);
  for (const [u, v] of roads) {
    graph[u].push(v);
    graph[v].push(u);
  }

  const visited: boolean[] = Array(n).fill(false);
  const ranks: number[] = Array(n).fill(0);

  for (let i = 0; i < n; i++) {
    if (!visited[i]) {
      dfs(i, 1);
    }
  }

  return Math.max(...ranks);

  function dfs(u: number, rank: number): void {
    visited[u] = true;
    ranks[u] = rank;
    for (const v of graph[u]) {
      if (!visited[v]) {
        dfs(v, rank + 1);
      }
    }
  }
}
```

