function process<T, R>(
  state: T,
  effect: (state: T) => R | None
): Channel<T, R> {
  return new Channel<T, R>(
    (send, receive) => {
      let state = state;
      let done = false;
      let error: Error | null = null;
      let closed = false;

      const effectHandler = (result: R | None) => {
        if (result.isSome()) {
          send(result.unwrap());
        } else if (result.isNone()) {
          done = true;
          closed = true;
          receive(state);
        } else {
          error = result.unwrap();
          done = true;
          closed = true;
          receive(state);
        }
      };

      const effectHandlerWrapper = () => effectHandler;

      const effectPromise = effect(state);
      effectPromise.then(effectHandlerWrapper);

      return () => {
        if (!closed) {
          closed = true;
          effectPromise.then(effectHandlerWrapper);
        }
      };
    }
  );
}
