function parsePassportData(data: string): object[] {
  const passports: object[] = [];
  const passport: object = {};

  for (const line of data.split("\n")) {
    if (line.length === 0) {
      passports.push(passport);
      passport = {};
    } else {
      for (const field of line.split(" ")) {
        const [key, value] = field.split(":");
        passport[key] = value;
      }
    }
  }

  passports.push(passport);

  return passports;
}
```

