      infos = data.split('.');
    }

    if (value.indexOf('/') != -1) {
      infos = data.split('/');
    }

    if (value.indexOf('-') != -1) {
      infos = data.split('-');
    }

    if (infos[2].length == 2) {
      dia = infos[2];
      ano = infos[0];
    } else if (infos[2].length == 4) {
      dia = infos[0];
      ano = infos[2];
    }

    mes = infos[1];
    data = `${ano}-${mes}-${dia} ${hora}`;
    return format(new Date(data), formato);
  } catch (erro) {
    return '';
  }
}

