function erode(image: number[][]): number[][] {
  const kernel = [
    [0, 0, 0],
    [0, 1, 0],
    [0, 0, 0],
  ];
  const result = [];
  for (let i = 0; i < image.length; i++) {
    result.push([]);
    for (let j = 0; j < image[i].length; j++) {
      let sum = 0;
      for (let k = 0; k < kernel.length; k++) {
        for (let l = 0; l < kernel[k].length; l++) {
          const x = i + k - 1;
          const y = j + l - 1;
          if (x >= 0 && x < image.length && y >= 0 && y < image[i].length) {
            sum += image[x][y] * kernel[k][l];
          }
        }
      }
      result[i].push(sum);
    }
  }
  return result;
}
```

