function findInValueExpr(node: ValueExprNode, outerRefsMap: OuterRefsMap): ReadonlyArray<UID> {
  switch (node.kind) {
    case NK.LIdent:
    case NK.UIdent:
      throw new Error('should have been resolved');

    case NK.NumLit:
    case NK.TextLit:
      return [];

    case NK.ValueRef:
    case NK.CtorRef:
      return [node.ref];

    case NK.FnDef:
      return findInFnDef(node, outerRefsMap);

    case NK.FnApp: {
      const subOrefs: Array<ReadonlyArray<UID>> = [];
      subOrefs.push(findInValueExpr(node.fn, outerRefsMap));
      for (const arg of node.args) {
        subOrefs.push(findInValueExpr(arg, outerRefsMap));
      }
      return subOrefs.flat();
    }

    case NK.Ifte:
      return [
        findInValueExpr(node.cond, outerRefsMap),
        findInValueExpr(node.cons, outerRefsMap),
        findInValueExpr(node.alt, outerRefsMap),
      ].flat();

    case NK.Block: {
      const orefs = findInStatements(node.stmts, outerRefsMap);
      outerRefsMap.set(node, new Set(orefs));
      return orefs;
    }
  }
}

