async function adaptContractInvoke<T = IEthereumSmartContractRawTxResponse>(contractInvokeReq: IEthereumSmartContractInvokeModel): Promise<T> {

  logger.info('Adapting contract invoke');

  const contract: any = new ETH.web3.eth.Contract(contractInvokeReq.abi, contractInvokeReq.to);
