function Use(...handlers: Handler[] | string[]): MethodDecorator {
	return (target: any, key: string | symbol, descriptor: PropertyDescriptor) => {

		let contains = false;

		if (!target.routes) {
			target.routes = [] as RouterDefinition[];
		}

		target.routes.forEach((element: RouterDefinition, idx: number) => {
			if (element.method === key) {
				if (!element.middlewares) {
					element.middlewares = [];
				}
				target.routes[idx] = {
					...element,
					middlewares: [
						...element.middlewares,
						...handlers
					]
				}
				contains = true;
			}
		});

		if (!contains) {
			target.routes.push({
				method: key,
				middlewares: handlers
			});
		}

		return descriptor;
	};
}

