  const newStructure = new Structure(structure.width, structure.height);

  for (let y = 0; y < structure.height; y++) {
    for (let x = 0; x < structure.width; x++) {
      const location = structure.get(x, y);
      const adjacent = structure.getAdjacent(x, y);

      if (location === "L" && adjacent.filter((l) => l === "#").length === 0) {
        newStructure.set(x, y, "#");
      } else if (location === "#" && adjacent.filter((l) => l === "#").length >= 5) {
        newStructure.set(x, y, "L");
      } else {
        newStructure.set(x, y, location);
      }
    }
  }

  return newStructure;
}
