function routeTo(delaunay: Delaunay, from: number, to: number): number[] {
  const path: number[] = [];
  let current = from;
  while (current !== to) {
    const next = delaunay.neighbors(current).find(
      (neighbor) => neighbor !== path[path.length - 1]
    );
    path.push(next);
    current = next;
  }
  return path;
}
```

