					...newState.slice(0, indexOfCharacter),
					new Character(character.name, character.stances, newStance, character.health, character.colors),
					...newState.slice(indexOfCharacter + 1)
				]
			}
			// Apply effects
			if (attack.effect) {
				switch (attack.effect) {
					case 'Battlecry': {
