  let remainingBytes = bytes;
  do {
    remainingBytes /= thresh;
    unit += 1;
  } while (Math.abs(remainingBytes) >= thresh && unit < units.length - 1);

  return `${remainingBytes.toFixed(2)}${units[unit]}`;
}

