function drawCircle(svg: SvgType, radius: number, currentDate: utils.DateFormatter) {
  const now = currentDate.getSecondsOfToday();
  const endAngle = convert(now);
  const startAngle = 0;
  const arc = d3.arc()
    .startAngle(startAngle)
    // .endAngle(endAngle)
    .outerRadius(radius);

  const teenFunction = (newEndAngle: number) => {
    return (d: d3.DefaultArcObject) => {
      const interpolateEndAngle = d3.interpolate(d.endAngle, newEndAngle);

      return (t: number) => {
        d.endAngle = interpolateEndAngle(t);
        return arc(d);
      };
    };
  };

  const fill = svg.append('path')
    .datum({
      endAngle: startAngle,
      innerRadius: 0
    })
    .attr('d', arc)
    .style('stroke', 'none')
    .style('fill', 'rgba(255,255,255,0.5)');

  const path = svg.append('path')
    .datum({
      endAngle: startAngle,
      innerRadius: radius
    })
    .attr('d', arc)
    .style('stroke', 'rgba(255,255,0,0.5)')
    // .style('stroke-dasharray', '5, 5')
    .style('fill', 'none')
    .style('stroke-width', 2);

  // rotation is in degrees and we start of on the left side of the circle
  const rotation = now * (360 / MAX_DAY_SECONDS);

  // https://stackoverflow.com/questions/22568803/rotating-an-svg-element-360-degrees-does-nothing
  const rotTween = () => {
    const i = d3.interpolate(0, rotation);
    return (t: number) => {
      return 'rotate(' + i(t) + ')';
    };
  };

  const sun = svg.append('circle')
    .datum({
      radius: 0,
      x_axis: 0,
      y_axis: -radius
    })
    .attr('cx', d => d.x_axis)
    .attr('cy', d => d.y_axis)
    .attr('r', d => d.radius)
    .classed('marker', true);

  sun.transition()
    .duration(1000)
    .attr('r', 10)
    .ease(d3.easeElastic)
    .on('end', () => {
      const duration = 1000;
      path.transition()
        .duration(duration)
        .attrTween('d', teenFunction(endAngle))
        .transition()
        .duration(duration)
        .style('opacity', 0);

      fill.transition()
        .duration(duration)
        .attrTween('d', teenFunction(endAngle))
        .transition()
        .duration(duration)
        .style('opacity', 0);

      sun.transition()
        .ease(d3.easeCubic)
        .duration(duration)
        .attrTween('transform', rotTween);
    });
}

