function createRelease(token: string, owner: string, repo: string, release: { name: string; body: string }): Promise<{ ok: boolean; err?: string }> {
  if (!token || !token.match(/^[a-z0-9]{40}$/)) {
    return Promise.resolve({ ok: false, err: "Invalid token" });
  }

  if (!owner || !repo) {
    return Promise.resolve({ ok: false, err: "Invalid owner or repo" });
  }

  return fetch(`https://api.github.com/repos/${owner}/${repo}/releases`, {
    method: "POST",
    headers: {
      Authorization: `token ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(release),
  }).then((res) => {
    if (res.ok) {
      return { ok: true };
    } else {
      return { ok: false, err: res.statusText };
    }
