function dilation(image: number[][]): number[][] {
  const kernel = [
    [0, 1, 0],
    [1, 1, 1],
    [0, 1, 0],
  ];
  const result = [];
  for (let i = 0; i < image.length; i++) {
    result.push([]);
    for (let j = 0; j < image[i].length; j++) {
      let sum = 0;
      for (let k = 0; k < kernel.length; k++) {
