            options = `
              <node id="${entryPoint ? entryPoint : node.options[0].id}" type="options">
                  <options>
                    ${node.options
                      .map(option => {
                        const nextNode = nodesById[option.nextNodeId];
                        const nextNodeId = nextNode ? nextNode.name : "";
                        return `<option 
                                  ${option.condition ? `if="${option.condition}"` : ""} 
