function zoomOut(
  start: number,
  end: number,
  duration: number,
  zoomFactor: number,
  zoomDuration: number
): [number, number] {
  const zoomStart = start + (end - start) * zoomFactor;
  const zoomEnd = end - (end - start) * zoomFactor;
  const zoomDurationMs = zoomDuration * 1000;
  const zoomStartMs = zoomStart * zoomDurationMs;
  const zoomEndMs = zoomEnd * zoomDurationMs;
  return [zoomStartMs, zoomEndMs];
}
