    const args = [
      '--config', tsConfigPath,
      files
    ];

    const spawn = require('cross-spawn');
    const cp = spawn(cmd, args);

    cp.on('error', (err: string) => {
      reject(new BuildError(`tslint error: ${err}`));
    });

