  const { toSemitones } = NOctave;
  const { toFrequency, toOctaves } = NMidi;
  const { toMidi } = NFrequency;

  function fromName(note: NoteName, sharps = true, tuning = A_440, strict = true): NoteProps {
    const { Tletter, Taccidental, Toct, Trest } = {
