    throw new Error(data.error);
  }

  if (data.distTags) {
    return data.distTags[version];
  }

  if (data.versions) {
    const versions = Object.keys(data.versions);
    const latestVersion = semver.maxSatisfying(versions, version);

    if (latestVersion) {
