function split(str: string, open: string, close: string, separator: string): string[] {
  const result: string[] = [];
  let current = "";
  let inBraces = false;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (char === open) {
      inBraces = true;
    } else if (char === close) {
      inBraces = false;
    } else if (inBraces) {
      current += char;
    } else if (char === separator) {
      result.push(current);
      current = "";
    }
  }

  if (current) {
    result.push(current);
  }

  return result;
}
```

