function until(
    condition: () => boolean,
    label: string,
    timeout: number
): Promise<void> {
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
            reject(new Error(`Timed out waiting for ${label}`));
        }, timeout);

        const checkCondition = () => {
            if (condition()) {
                clearTimeout(timer);
                resolve();
            } else {
                setTimeout(checkCondition, 100);
            }
        };

        checkCondition();
    });
}
