function listString(
  items: string[],
  conjunction: string = "and",
  article: string = "the",
  separator: string = ", "
): string {
  if (items.length === 0) {
    return "";
  }

  if (items.length === 1) {
    return items[0];
  }

  if (items.length === 2) {
    return `${items[0]} ${conjunction} ${items[1]}`;
