function rgbToHsl(r: number, g: number, b: number): number[] {
  const [min, max] = [Math.min(r, g, b), Math.max(r, g, b)];
  const l = (min + max) / 2;
  const s = l === 0 ? 0 : (max - min) / (1 - Math.abs(2 * l - 1));
  const h =
    max === min
      ? 0
      : max === r
      ? (g - b) / (max - min)
      : max === g
      ? 2 + (b - r) / (max - min)
      : 4 + (r - g) / (max - min);
  return [h * 60, s * 100, l * 100];
}
```

