function binOpStr(
        ctrSet: ConstraintSet,
        left: SVString,
        right: SVString,
        bop: TEBopType,
        source?: ExpressionNode
    ): ShValue | undefined {
        if (typeof left.value === 'string' && typeof right.value === 'string') {
            return binOpStrLiteral(left.value, right.value, bop, source);
        }

        const leftExp = typeof left.value === 'string' ? ExpString.fromConst(left.value) : left.value;
        const rightExp = typeof right.value === 'string' ? ExpString.fromConst(right.value) : right.value;
        let symName: string | undefined;

        switch (bop) {
            case TEBopType.Add:
                return SVString.create(ExpString.concat(leftExp, rightExp, source), source);
            case TEBopType.Eq:
            case TEBopType.Is:
                return SVBool.create(ExpBool.eq(leftExp, rightExp, source), source);
            case TEBopType.Neq:
            case TEBopType.IsNot:
                return SVBool.create(ExpBool.neq(leftExp, rightExp, source), source);
