		const query = getPool(credentials).query({
			sql: peek(sql),
			values: params ? peek(params) : [],
		});
		query.on("result", (record: any) => send!(Object.assign({}, record)));
		query.on("end", resolve);
		query.on("error", reject);
	})).then((value) => {
		channel.close();
		return records;
	}, (error) => {
		channel.close();
		throw error;
	});
}

