function increasingTriplet(nums: number[]): boolean {
  let min = Infinity;
  let mid = Infinity;

  for (let num of nums) {
    if (num <= min) {
      min = num;
    } else if (num <= mid) {
      mid = num;
    } else {
      return true;
    }
  }

  return false;
}
