function start(parent: Element | string, tree: any, ctx?: any, spans = true) {
  let prev = [];
  let isActive = true;
  parent = isString(parent) ? document.getElementById(parent) : parent;
  function update() {
    if (isActive) {
      const curr = normalizeTree(tree, ctx, [0], true, spans);
      if (curr != null) {
        diffElement(<Element>parent, prev, curr);
        prev = curr;
      }
      // check again in case one of the components called cancel
    }
  }
  function cancel() {
    isActive = false;
  }
  update();
  return cancel;
}
