    if (tag.startsWith('<')) {
      const tagName = tag.slice(1, tag.indexOf(' '));
      current = new TagNode(tagName);
      current.parent = root;
      root.children.push(current);
    } else if (tag.startsWith('</')) {
      current = current.parent;
    } else {
      const text = tag.slice(0, -1);
      current.children.push(new TextNode(text));
