      if (!keys.includes(key)) {
        keys.push(key)
      }
    })
  }

  return keys.filter((key: string) => {
    if (key === 'constructor') {
      return false
    }

    if (typeof objectOrKlass[key] !== 'function') {
      return false
    }
    return true
  })
}

