function useBreakpointDetection(
  enabled: boolean,
  breakpoints: string[],
  setBreakpoint: (index: number, matches: boolean) => void,
) {
  useEffect(() => {
    if (!enabled) return;

    const mediaQueryLists = breakpoints.map(
      breakpoint => window.matchMedia(`(min-width: ${breakpoint}px)`),
    );

    const updateBreakpoint = (index: number, matches: boolean) => {
      setBreakpoint(index, matches);
    };

    mediaQueryLists.forEach((mediaQueryList, index) => {
      mediaQueryList.addEventListener("change", () => {
        updateBreakpoint(index, mediaQueryList.matches);
      });
    });
  }, [enabled, breakpoints, setBreakpoint]);
}
```

-- Explanation:
This function uses the useEffect hook to detect when the window's media queries change and update the breakpoint state.

