function averageGeoPoint(points: GeoPoint[]): GeoPoint | undefined {
  if (points.length === 0) {
    return undefined;
  }

  const latitudeSum = points.reduce((sum, point) => sum + point.latitude, 0);
  const longitudeSum = points.reduce((sum, point) => sum + point.longitude, 0);

  const averageLatitude = latitudeSum / points.length;
  const averageLongitude = longitudeSum / points.length;

  return { latitude: averageLatitude, longitude: averageLongitude };
}
