async function waitForBuild(
  projectId: string,
  buildId: string,
  client: BuildServiceClient
): Promise<Build> {
  const build = await client.getBuild({
    projectId,
    id: buildId,
  });

  while (build.status !== "SUCCESS" && build.status !== "FAILURE") {
    await new Promise((resolve) => setTimeout(resolve, 1000));
    build = await client.getBuild({
      projectId,
