function ReportExceptionsToConsole() {
    return Mutator.define({
        options: { 
            validTargets: ['method'] 
        },

        invoke(site) {
            let originalMethod : Function = site.propertyDescriptor.value;
            site.propertyDescriptor.value = function (...args) {
                let type : Function;
                let isStatic : boolean = false;

                if (typeof site.target === 'function') {
                    type = site.target;
                    isStatic = true;
                } else {
                    type = site.target.constructor;
                    isStatic = false;
                }

                let typeName : string;
                let sep : string = '.';

                if (isStatic)
                    sep = '#';

                typeName = type.name;

