  attester: AttesterIdentity,
  message: IMessage,
  claimer: PublicIdentity,
  session: gabi.AttesterAttestationSession | null = null,
  requirePE = false
): Promise<{
  revocationHandle: IRevocationHandle
  message: Message
}> {
