    throw ERROR_MESSAGE_TYPE(
      message.body.type,
      MessageBodyType.REQUEST_ATTESTATION_FOR_CLAIM
    )
  }
  if (requirePE && session === null) {
    throw ERROR_ATTESTATION_SESSION_MISSING()
  }

  const request: IRequestAttestationForClaim = message.body
