function useMethods(
  methods: Methods,
  initialState: State,
  initializer?: Initializer
): [State, Callbacks] {
  const [state, setState] = useState(initialState);
  const callbacks = useMemo(() => {
    const callbacks: Callbacks = {};
    for (const key in methods) {
      callbacks[key] = (...args: any[]) => {
        const result = methods[key](state, ...args);
        setState(result);
      };
    }
    return callbacks;
  }, [methods, state]);
  useEffect(() => {
    if (initializer) {
      const result = initializer(state);
      setState(result);
    }
  }, [initializer, state]);
  return [state, callbacks];
}
```

