function calculateMonthlyMinimumInstanceCost(
  endpoints: number[]
): number {
  const sortedEndpoints = endpoints.sort((a, b) => a - b);
  let minCost = 0;
  let currentCost = 0;
  let currentEndpoint = 0;
  for (let i = 0; i < sortedEndpoints.length; i++) {
    const endpoint = sortedEndpoints[i];
    if (endpoint > currentEndpoint) {
      currentCost += endpoint - currentEndpoint;
      currentEndpoint = endpoint;
    }
    minCost = Math.min(minCost, currentCost);
  }
  return minCost;
}
