			hint_string: '',
			default: typeof(default_value) === 'string' ? default_value : 0
		};
		for (let i = 0; i < enumeration.length; i++) {
			pi.hint_string += enumeration[i];
			if (i < enumeration.length - 1) {
				pi.hint_string += ',';
			}
		}
		godot.register_property(target, property, pi);
		return descriptor;
	}
}

function apiRoutesHandler(routeHandler: RouteHandler) {
  return (req: NextApiRequest, res: NextApiResponse) => {
    const {method} = req
    if (!method || !Object.keys(routeHandler).includes(method)) {
      res.setHeader('Allow', Object.keys(routeHandler))
      return res.status(405).end(`Method ${method} Not Allowed`)
    }
    return routeHandler[method](req, res)
  }
}

