function useDelayedUnmount(mounted: boolean, delay: number): boolean {
  const [shouldRender, setShouldRender] = useState(false);

  useEffect(() => {
    if (mounted) {
      setShouldRender(true);
      setTimeout(() => setShouldRender(false), delay);
    } else {
      setTimeout(() => setShouldRender(false), delay);
    }
  }, [mounted, delay]);

  return shouldRender;
}
