function getIntervalStyle(
  baseStyle: CSSProperties,
  start: number,
  end: number,
  intervalStart: number,
  intervalEnd: number
): CSSProperties {
  const style = { ...baseStyle };
  if (start < intervalStart) {
    style.left = `${start}px`;
  } else if (start > intervalEnd) {
    style.left = `${intervalEnd}px`;
  } else {
    style.left = `${intervalStart}px`;
  }
  if (end < intervalStart) {
    style.width = `${intervalStart - start}px`;
  } else if (end > intervalEnd) {
    style.width = `${intervalEnd - start}px`;
  } else {
    style.width = `${end - start}px`;
  }
  return style;
}
