function useSWRContract(
  contract: Contract,
  method: string,
  args: any[],
  options?: any
): any {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const result = await contract[method](...args, options);
        setData(result);
      } catch (e) {
        setError(e);
      }
    };
    fetchData();
  }, [contract, method, args, options]);

