function calculateContentFingerprint(filePath: string): string {
  const fileContents = fs.readFileSync(filePath);
  const isBinary = fileContents.includes(0);
  const normalizedContents = isBinary ? fileContents : fileContents.replace(/\r\n/g, "\n");
  const hash = crypto.createHash("sha256").update(normalizedContents).digest("hex");
  const size = normalizedContents.length;
  return `${size}:${hash}`;
}
