function getWriteFunction(metadata: SerializerMetadata): Write {
  const { properties, propertyMetadata } = metadata;
  return (object: any, stream: WritableStream) => {
    for (const property of properties) {
      const propertyMetadata = propertyMetadata[property];
      const value = object[property];
      if (propertyMetadata.type === "object") {
        getWriteFunction(propertyMetadata.metadata)(value, stream);
      } else {
        stream.write(value);
      }
    }
  };
}
```

