function _partition<T>(
  items: T[],
  left: number,
  right: number,
  comparer: (a: T, b: T) => number
): number {
  const pivot = items[right];
  let i = left;
  for (let j = left; j < right; j++) {
    if (comparer(items[j], pivot) <= 0) {
      [items[i], items[j]] = [items[j], items[i]];
      i++;
    }
  }
  [items[i], items[right]] = [items[right], items[i]];
  return i;
}
