function targetInstancesByTimeZone(
  instance: Instance,
  targets: Targets,
): TargetInstance[] {
  const currentTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  return Object.entries(targets).reduce((acc, [targetId, target]) => {
    if (target.Timezone?.timezone === currentTimeZone) {
      acc.push({
        campaign: instance.campaign,
        target: targetId,
      });
    }
    return acc;
  }, []);
}
