      url = matched;
    }

    url = `${origin || ''}${url}`;

    const requestConfig: AnyObject = {
      url,
      method,
      ...rest.reduce((map, current) => {
        return { ...map, ...current };
      }, {}),
    };

    const requestFormattedConfig = params ? setParams!(method, params, requestConfig as T) : requestConfig;

    // @ts-ignore
    const task: any = request(requestFormattedConfig);

    if (beforeRequest) {
      beforeRequest(task);
    }

    return task;
  };
}

