function determinant(m: Array<Array<number>>): number {
  let len = m.length;
  let res = 0;
  if (len === 1) {
    return m[0][0];
  }
  let temp: Array<Array<number>> = [];
  for (let i = 0; i < len - 1; i++) {
    temp[i] = [];
  }
  let flag = 1;

  for (let i = 0; i < len; i++) {
    // clear temp
    for (let i = 0; i < len - 1; i++) {
      temp[i] = [];
    }
    for (let j = 0; j < len; j++) {
      if (j === i) {
        continue;
      }
      for (let k = 0; k < len - 1; k++) {
        temp[k] = [];
      }
      for (let k = 0; k < len - 1; k++) {
        temp[k][j] = m[k + 1][j];
      }
      res += flag * m[0][i] * determinant(temp);
      flag = -flag;
    }
  }
  return res;
}

