function generateSearchQuery(fileName: string, parent: string | string[], duplicateMirror = false): string {
  if (Array.isArray(parent)) {
    var q: string;
    q = '(';
    parent.forEach((element, key) => {
      if (parent.length === key + 1) {
        q += '\'' + element + '\' in parents)';
      } else {
        q += '\'' + element + '\' in parents or ';
      }
    });
    q += ' and (';
  } else {
    var q = '\'' + parent + '\' in parents and (';
  }
  if (fileName.indexOf(' ') > -1) {
    for (var i = 0; i < 4; i++) {
      q += duplicateMirror ? 'name = \'' + fileName + '\' ' : 'name contains \'' + fileName + '\' ';
      switch (i) {
        case 0:
          fileName = fileName.replace(/ /g, '.');
          q += 'or ';
          break;
        case 1:
          fileName = fileName.replace(/\./g, '-');
          q += 'or ';
          break;
        case 2:
          fileName = fileName.replace(/-/g, '_');
          q += 'or ';
          break;
      }
    }
  } else {
    q += duplicateMirror ? 'name = \'' + fileName + '\'' : 'name contains \'' + fileName + '\'';
  }
  q += ') and trashed = false';
  return q;
}

