function findOverlappingEntries(entries: string[][]): string[][] {
  const overlappingEntries: string[][] = [];

  for (let i = 0; i < entries.length; i++) {
    const [startTime, endTime] = entries[i];

    for (let j = i + 1; j < entries.length; j++) {
      const [nextStartTime, nextEndTime] = entries[j];

      if (startTime < nextEndTime && endTime > nextStartTime) {
        overlappingEntries.push([startTime, endTime]);
        break;
      }
    }
  }

  return overlappingEntries;
}
```

