function parseKeyValue(parser: TomlParser): TomlKeyValue | undefined {
	const pos = parser.getPosition();
	let value: AnyTomlValue | undefined = undefined;
	const key: TomlKey | undefined = parseKey(parser);
	if (!key) {
		return undefined;
	}

	parser.nextToken();

	const valueToken = parser.getToken();

	switch (valueToken.type) {
		case "DoubleQuote": {
			value = parseText(parser);
			if (!value) {
				return undefined;
			}
			parser.nextToken();
			return parser.finishNode(
				pos,
				{
					type: "TomlKeyValue",
					key,
					value,
				},
			);
		}
	}

	if (!value) {
		parser.unexpectedDiagnostic({
			description: descriptions.TOML_PARSER.VALUE_NOT_RECOGNISED(key.value),
		});
		parser.nextToken();
		return undefined;
	}

	parser.nextToken();
	return undefined;
}

