function parseTOML(toml: string): { [key: string]: string } {
  const result: { [key: string]: string } = {};
  const lines = toml.split("\n");
  for (const line of lines) {
    const [key, value] = line.split("=");
    result[key] = value;
  }
  return result;
}
```

